<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue';import { CheckCircle2, Clock3, FileSearch, Play, RefreshCw, Save } from 'lucide-vue-next';import { ElMessage } from 'element-plus';import { api } from '../api';import OperationsMap from '../components/OperationsMap.vue';import PageHeader from '../components/PageHeader.vue';import type { AccidentAnalysisItem, PageData, TrackPoint } from '../types';
const loading=ref(false),detailLoading=ref(false),items=ref<AccidentAnalysisItem[]>([]),total=ref(0),selected=ref<any>(null),mapRef=ref<InstanceType<typeof OperationsMap>|null>(null),dialog=ref(false);const query=reactive({page:1,pageSize:20,q:'',level:'',status:''});const form=reactive({windowMinutes:30,primaryCause:'',contributingFactor:'',conclusion:'',recommendation:'',status:'DRAFT'});const levelText=(v:string)=>({LOW:'低',MEDIUM:'一般',HIGH:'较大',CRITICAL:'重大'} as any)[v]??v;const statusText=(v:string)=>({REPORTED:'已上报',INVESTIGATING:'调查中',CLOSED:'已关闭',DRAFT:'草稿',COMPLETED:'已完成'} as any)[v]??v;const timeline=computed(()=>{if(!selected.value)return[];const rows=[...(selected.value.evidence?.alerts??[]).map((x:any)=>({time:x.occurredAt,type:'告警',title:x.title})),...(selected.value.evidence?.violations??[]).map((x:any)=>({time:x.occurredAt,type:'违规',title:x.title})),{time:selected.value.occurredAt,type:'事故',title:selected.value.title}];return rows.sort((a,b)=>new Date(a.time).getTime()-new Date(b.time).getTime())});
async function load(){loading.value=true;try{const p=new URLSearchParams({page:String(query.page),pageSize:String(query.pageSize)});if(query.q)p.set('q',query.q);if(query.level)p.set('level',query.level);if(query.status)p.set('status',query.status);const result=await api<PageData<AccidentAnalysisItem>>(`/analytics/accidents?${p}`);items.value=result.items;total.value=result.total;if(!selected.value&&items.value[0])await open(items.value[0])}catch(e){ElMessage.error(e instanceof Error?e.message:'事故列表加载失败')}finally{loading.value=false}}async function open(item:AccidentAnalysisItem){detailLoading.value=true;try{selected.value=await api<any>(`/analytics/accidents/${item.id}?windowMinutes=30`)}finally{detailLoading.value=false}}function edit(){const r=selected.value?.reconstruction;Object.assign(form,{windowMinutes:r?.windowMinutes??30,primaryCause:r?.causes?.primaryCause??'',contributingFactor:r?.causes?.contributingFactor??'',conclusion:r?.conclusion??'',recommendation:r?.recommendation??'',status:r?.status??'DRAFT'});dialog.value=true}async function save(){await api(`/analytics/accidents/${selected.value.id}/reconstruction`,{method:'POST',body:JSON.stringify(form)});ElMessage.success(form.status==='COMPLETED'?'回溯结论已完成':'回溯草稿已保存');dialog.value=false;await open(selected.value);await load()}onMounted(load);
</script>
<template><PageHeader title="事故回溯" description="关联运行轨迹、车辆状态、告警与违规证据，形成可审计的事故复盘结论。"><el-button :icon="RefreshCw" :loading="loading" @click="load">刷新</el-button></PageHeader><section class="phase6-filter"><el-input v-model="query.q" clearable placeholder="事故编号、标题或车辆" style="width:250px" @keyup.enter="load"/><el-select v-model="query.level" clearable placeholder="事故等级" style="width:130px"><el-option v-for="x in ['LOW','MEDIUM','HIGH','CRITICAL']" :key="x" :label="levelText(x)" :value="x"/></el-select><el-select v-model="query.status" clearable placeholder="处置状态" style="width:140px"><el-option label="已上报" value="REPORTED"/><el-option label="调查中" value="INVESTIGATING"/><el-option label="已关闭" value="CLOSED"/></el-select><el-button type="primary" @click="load">查询</el-button></section><div class="reconstruction-layout"><section class="phase6-panel accident-list"><header><div><strong>事故档案</strong><span>{{total}} 起纳入回溯</span></div></header><button v-for="x in items" :key="x.id" :class="{active:selected?.id===x.id}" @click="open(x)"><i :class="x.level"></i><div><strong>{{x.title}}</strong><span>{{x.businessNo}} · {{x.enterprise.name}}</span><small>{{new Date(x.occurredAt).toLocaleString('zh-CN')}}</small></div><em>{{x.reconstruction?statusText(x.reconstruction.status):'待回溯'}}</em></button><el-empty v-if="!items.length" description="暂无事故记录" :image-size="72"/></section><section v-if="selected" class="reconstruction-main" v-loading="detailLoading"><article class="phase6-panel reconstruction-summary"><header><div><strong>{{selected.title}}</strong><span>{{selected.businessNo}} · {{selected.enterprise.name}} · {{selected.vehicle.name}}</span></div><el-button type="primary" :icon="FileSearch" @click="edit">形成回溯结论</el-button></header><div class="evidence-metrics"><span><Clock3/><b>{{selected.window.minutes}} 分钟</b><small>证据窗口</small></span><span><FileSearch/><b>{{selected.summary.trackPoints}}</b><small>轨迹点</small></span><span><Play/><b>{{selected.summary.maxSpeed}} km/h</b><small>窗口最高车速</small></span><span><CheckCircle2/><b>{{selected.summary.alerts+selected.summary.violations}}</b><small>关联风险事件</small></span></div></article><article class="phase6-panel"><header><div><strong>时空轨迹复现</strong><span>事故前后 {{selected.window.minutes}} 分钟 · {{selected.evidence.operationRecord?.businessNo??'未关联运行记录'}}</span></div><el-button :icon="Play" :disabled="!selected.evidence.track.length" @click="mapRef?.playTrack()">播放轨迹</el-button></header><OperationsMap ref="mapRef" mode="trajectory" :track="selected.evidence.track as TrackPoint[]" height="420px"/></article><section class="phase6-chart-grid"><article class="phase6-panel"><header><div><strong>证据时间线</strong><span>仅展示事故窗口内关联事件</span></div></header><el-timeline><el-timeline-item v-for="x in timeline" :key="x.time+x.type" :timestamp="new Date(x.time).toLocaleString('zh-CN')" :type="x.type==='事故'?'danger':x.type==='告警'?'warning':'primary'"><b>{{x.type}}</b> · {{x.title}}</el-timeline-item></el-timeline><el-empty v-if="timeline.length===1" description="除事故外暂无关联事件" :image-size="60"/></article><article class="phase6-panel"><header><div><strong>回溯结论</strong><span>由监管人员基于证据形成</span></div><el-tag :type="selected.reconstruction?.status==='COMPLETED'?'success':'info'">{{selected.reconstruction?statusText(selected.reconstruction.status):'待形成'}}</el-tag></header><template v-if="selected.reconstruction"><dl class="analysis-dl"><dt>主要原因</dt><dd>{{selected.reconstruction.causes.primaryCause}}</dd><dt>辅助因素</dt><dd>{{selected.reconstruction.causes.contributingFactor||'—'}}</dd><dt>分析结论</dt><dd>{{selected.reconstruction.conclusion}}</dd><dt>整改建议</dt><dd>{{selected.reconstruction.recommendation||'—'}}</dd></dl></template><el-empty v-else description="尚未形成回溯结论" :image-size="70"/></article></section></section><section v-else class="phase6-panel selection-empty"><el-empty description="请选择事故档案"/></section></div><el-dialog v-model="dialog" title="事故回溯结论" width="640px"><el-form label-position="top"><div class="form-grid"><el-form-item label="证据窗口"><el-input-number v-model="form.windowMinutes" :min="10" :max="120"/><span class="form-suffix">分钟</span></el-form-item><el-form-item label="结论状态"><el-radio-group v-model="form.status"><el-radio-button value="DRAFT">保存草稿</el-radio-button><el-radio-button value="COMPLETED">完成回溯</el-radio-button></el-radio-group></el-form-item></div><el-form-item label="主要原因"><el-input v-model="form.primaryCause" maxlength="200" show-word-limit/></el-form-item><el-form-item label="辅助因素"><el-input v-model="form.contributingFactor" maxlength="200"/></el-form-item><el-form-item label="分析结论"><el-input v-model="form.conclusion" type="textarea" :rows="4" maxlength="1000" show-word-limit/></el-form-item><el-form-item label="整改建议"><el-input v-model="form.recommendation" type="textarea" :rows="3" maxlength="600"/></el-form-item></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" :icon="Save" @click="save">保存</el-button></template></el-dialog></template>
